import itertools

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_strings(n):
    # Generates all binary strings of length n
    return ["".join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]

def calculate_D(S, n, k):
    """
    Calculates the set D(S): all n-digit binary strings S' such that
    Hamming distance d(S, S') = k.
    """
    D_S = set()
    # Iterate through all possible n-digit strings S'
    all_strings = generate_strings(n)
    for S_prime in all_strings:
        if hamming_distance(S, S_prime) == k:
            D_S.add(S_prime)
    return D_S

