    """
    Calculates the set D(S) for all possible strings S of length n,
    where D(S) is the set of strings at Hamming distance exactly k from S.
    Returns a dictionary mapping string S to its set D(S).
    """
    all_strings = [''.join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]
    D_sets = {}

    for s in all_strings:
